#include <iostream>
#include <stdexcept>
void myFunction() throw() {
  // Code that was intended to not throw exceptions
  // ... but might throw unexpectedly from a called function.
  if (true) throw std::runtime_error("oops!");
}
int main() {
  try {
    myFunction();
  } catch (const std::exception& e) {
    std::cerr << "Caught exception: " << e.what() << std::endl;
  }
  return 0;
}
